window.M = (id) => document.querySelector('[data-metric=' + id + ']')?.innerText.replace(/\n/g, ' | ') ?? 'MISSING';
window.L = (re, n = 6) => document.body.innerText.split('\n').map((l) => l.trim()).filter((l) => re.test(l)).slice(0, n);
window.until = async (fn, ms = 8000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await new Promise((r) => setTimeout(r, 150)) } return false };
window.nav = (name) => [...document.querySelectorAll('nav button')].find((b) => b.textContent.trim() === name).click();
window.board = () => { const rows = [...document.querySelectorAll('tbody tr')]; return { h1: document.querySelector('h1')?.innerText, heads: [...document.querySelectorAll('thead th')].map((h) => h.innerText.replace(/\n/g, ' ')).filter(Boolean).slice(0, 16), first: rows[0]?.innerText.replace(/\s*\n\s*/g, ' | ').slice(0, 260), blanks: rows.slice(0, 20).reduce((n, r) => n + [...r.querySelectorAll('td')].filter((c) => c.innerText.trim() === '—').length, 0), rows: rows.length } };
window.openPlayer = async (name) => { const input = document.querySelector('input[aria-label="Search players"]'); const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, name); input.dispatchEvent(new Event('input', { bubbles: true })); await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED'; b.click(); await until(() => document.querySelector('h1')?.innerText.replace(/\n/g, ' ').includes(name.split(' ').pop())); return 'opened ' + document.querySelector('h1')?.innerText.replace(/\n/g, ' ') };
window.tab = async (label) => { const t = [...document.querySelectorAll('[role=tab]')].find((x) => x.textContent.trim() === label); if (!t) return 'NO TAB ' + label; t.click(); await new Promise((r) => setTimeout(r, 900)); return 'tab ' + label };
window.openTeam = async (name) => { await until(() => [...document.querySelectorAll('button[role=row]')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('button[role=row]')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT FOUND'; b.click(); await until(() => document.querySelector('h1')?.textContent.includes(name.split(' ').pop())); return 'opened ' + document.querySelector('h1')?.textContent };
